import type { ControlUiSkin } from "@/components/control-ui/skin";

export const skin: ControlUiSkin = {
  id: "windows-98",
  motion: "reduced",
  colorScheme: "light",
  sidebarLayout: "sidebar",
  indicators: { sidebar: "none", tree: "none" },
  adornments: {
    "chat-layout": {
      titlebar: (
        <div
          aria-hidden="true"
          className="flex h-5 shrink-0 select-none items-center bg-[image:var(--win98-titlebar)] px-1 text-[11px] font-bold text-[var(--win98-white)]"
        >
          Agent Chat
        </div>
      ),
    },
  },
};

@import "../retro-system-font.css";

@import "./windows-98-controls.css";

[data-skin="windows-98"] {
  --win98-white: oklch(1 0 0);
  --win98-light: oklch(0.9037 0 0);
  --win98-shadow: oklch(0.5999 0 0);
  --win98-dark: oklch(0.1448 0 0);
  --win98-face: var(--secondary);
  --win98-raised:
    inset -1px -1px var(--win98-dark), inset 1px 1px var(--win98-white), inset -2px -2px var(--win98-shadow),
    inset 2px 2px var(--win98-light);
  --win98-sunken:
    inset -1px -1px var(--win98-white), inset 1px 1px var(--win98-shadow), inset -2px -2px var(--win98-light),
    inset 2px 2px var(--win98-dark);
  --win98-pressed:
    inset -1px -1px var(--win98-white), inset 1px 1px var(--win98-dark), inset -2px -2px var(--win98-light),
    inset 2px 2px var(--win98-shadow);
  --win98-titlebar: linear-gradient(90deg, oklch(0.2711 0.1879 264.052), oklch(0.594 0.1477 245.841));
  --win98-tooltip: oklch(0.9922 0.039 107.089);
}

@layer components {
  [data-skin="windows-98"]
    :where(
      [data-control-family="popup"][data-popup-part="surface"],
      [data-control-family="popup"][data-popup-part="list-surface"],
      [data-control-family="popup"][data-popup-part="bar"]
    ) {
    --cui-popup-radius: 0px;
    --cui-popup-background: var(--win98-face);
    --cui-popup-foreground: var(--foreground);
    --cui-popup-border-width: 0px;
    --cui-popup-shadow: var(--win98-raised);
    --cui-popup-backdrop-filter: none;
    --cui-popup-item-radius: 0px;
    --cui-popup-item-highlight-background: var(--primary);
    --cui-popup-item-highlight-foreground: var(--primary-foreground);
    --cui-popup-item-highlight-muted-foreground: var(--primary-foreground);
    --cui-popup-separator-color: var(--win98-shadow);
  }
  [data-skin="windows-98"] :where([data-control-family="popup"][data-popup-part="list-surface"]) {
    padding: 3px;
  }
  [data-skin="windows-98"] :where([data-control-family="popup"][data-popup-part="item"]) {
    min-block-size: 20px;
    padding-block: 2px;
  }
  [data-skin="windows-98"] :where([data-control-family="popup"][data-popup-part="separator"]) {
    box-shadow: 0 1px var(--win98-white);
  }
  [data-skin="windows-98"] :where([data-control-family="popup"][data-popup-part="label"]) {
    text-transform: none;
    letter-spacing: normal;
  }
  [data-skin="windows-98"]
    :where([data-control-family="popup"][data-popup-part="surface"]:is([data-popup-kind="dialog"], [data-popup-kind="alert-dialog"])) {
    padding: 3px;
    gap: 12px;
  }
  [data-skin="windows-98"]
    :where([data-control-family="popup"][data-slot="header"]:is([data-popup-kind="dialog"], [data-popup-kind="alert-dialog"])) {
    padding: 0;
    gap: 12px;
  }
  [data-skin="windows-98"]
    :where([data-control-family="popup"][data-slot="title"]:is([data-popup-kind="dialog"], [data-popup-kind="alert-dialog"])) {
    min-block-size: 20px;
    padding: 4px 27px 4px 3px;
    background: var(--win98-titlebar);
    color: var(--win98-white);
    font: 700 11px / 12px var(--font-sans);
    letter-spacing: normal;
  }
  [data-skin="windows-98"]
    :where([data-control-family="popup"][data-slot="description"]:is([data-popup-kind="dialog"], [data-popup-kind="alert-dialog"])) {
    padding-inline: 9px;
    color: var(--foreground);
  }
  [data-skin="windows-98"] :where([data-control-family="button"][data-popup-part="close"][data-icon-only="true"]) {
    opacity: 1;
    --cui-button-background: var(--win98-face);
    --cui-button-shadow: var(--win98-raised);
    --cui-button-hover-shadow: var(--win98-raised);
    --cui-button-height: 16px;
    --cui-button-icon: 10px;
    top: 5px;
    right: 5px;
    width: 18px;
    aspect-ratio: auto;
  }
  [data-skin="windows-98"] :where([data-control-family="popup"][data-popup-kind="tooltip"][data-popup-part="surface"]) {
    --cui-popup-background: var(--win98-tooltip);
    --cui-popup-border-width: 1px;
    --cui-popup-border-color: var(--foreground);
    --cui-popup-shadow: 1px 1px var(--win98-shadow);
  }
  [data-skin="windows-98"] :where([data-control-family="sidebar"][data-slot="root"]) {
    --cui-sidebar-inner-background: var(--win98-face);
    --cui-sidebar-inner-background-image: none;
    --cui-sidebar-inner-border-width: 0px;
    --cui-sidebar-inner-radius: 0px;
    --cui-sidebar-inner-shadow: var(--win98-raised);
    --cui-sidebar-group-label-foreground: var(--foreground);
    --cui-sidebar-menu-button-radius: 0px;
    --cui-sidebar-menu-button-foreground: var(--foreground);
    --cui-sidebar-menu-button-hover-background: transparent;
    --cui-sidebar-menu-button-hover-foreground: var(--foreground);
    --cui-sidebar-menu-button-active-background: var(--primary);
    --cui-sidebar-menu-button-active-foreground: var(--primary-foreground);
  }
  [data-skin="windows-98"]
    :where([data-control-family="sidebar"][data-slot="inner"] [data-control-family="scroll-area"][data-slot="root"]) {
    margin: 0 4px;
    padding: 3px;
    background: var(--background);
    box-shadow: var(--win98-sunken);
  }
  [data-skin="windows-98"] :where([data-control-family="sidebar"][data-slot="content-stack"]) {
    gap: 0;
  }
  [data-skin="windows-98"] :where([data-control-family="sidebar"][data-slot="group"]) {
    padding: 0 3px;
  }
  [data-skin="windows-98"] :where([data-control-family="sidebar"][data-slot="group-label"]) {
    padding-inline: 4px;
    min-block-size: 22px;
    font-weight: 400;
    text-transform: none;
    letter-spacing: normal;
  }
  [data-skin="windows-98"] :where([data-control-family="sidebar"][data-slot="menu"]) {
    margin-inline-start: 9px;
    border-inline-start: 1px dotted var(--win98-shadow);
    padding-inline-start: 6px;
  }
  [data-skin="windows-98"] :where([data-control-family="sidebar"][data-slot="menu"]) {
    gap: 0;
  }
  [data-skin="windows-98"] :where([data-control-family="sidebar"][data-slot="menu"] [data-control-family="sidebar"][data-slot="menu"]) {
    border-inline-start: 1px dotted var(--win98-shadow);
  }
  [data-skin="windows-98"] :where([data-control-family="sidebar"][data-slot="menu-button"]) {
    min-block-size: 20px;
    height: auto;
    padding: 3px 4px;
  }
  [data-skin="windows-98"] :where([data-control-family="tree"][data-slot="root"]) {
    --cui-tree-item-trigger-radius: 0px;
    --cui-tree-item-trigger-selected-background: var(--primary);
    --cui-tree-item-trigger-selected-foreground: var(--primary-foreground);
    background: var(--background);
    box-shadow: var(--win98-sunken);
    padding: 3px;
  }
  [data-skin="windows-98"] :where([data-control-family="tree"][data-slot="item-trigger"]) {
    padding-block: 2px;
  }
  [data-skin="windows-98"] :where([data-control-family="card"][data-slot="root"]) {
    --cui-card-radius: 0px;
    --cui-card-background: var(--win98-face);
    --cui-card-border-color: transparent;
    --cui-card-shadow: var(--win98-raised);
  }
  [data-skin="windows-98"] :where([data-control-family="table"][data-slot="root"]) {
    --cui-table-background: var(--background);
    box-shadow: var(--win98-sunken);
  }
  [data-skin="windows-98"] :where([data-control-family="table"][data-slot="head"]) {
    background: var(--win98-face);
    box-shadow: var(--win98-raised);
  }
  [data-skin="windows-98"] :where([data-control-family="kbd"][data-slot="root"]) {
    --cui-kbd-radius: 0px;
    --cui-kbd-background: var(--win98-face);
    --cui-kbd-shadow: var(--win98-raised);
  }
  [data-skin="windows-98"] :where([data-control-family="chat-layout"][data-control-ui="chat-layout"][data-slot="root"]) {
    --cui-chat-layout-radius: 0px;
    --cui-chat-layout-border-color: transparent;
    --cui-chat-layout-shadow: var(--win98-raised);
    border-width: 0;
    padding: 3px;
  }
  [data-skin="windows-98"] :where([data-control-family="chat-message"][data-slot="root"][data-role="user"]) {
    --cui-chat-message-foreground: var(--foreground);
    --cui-chat-message-radius: 0px;
    --cui-chat-message-corner-radius: 0px;
    --cui-chat-message-background: var(--background);
    --cui-chat-message-border-width: 0px;
    --cui-chat-message-shadow: var(--win98-sunken);
  }
  [data-skin="windows-98"] :where([data-control-family="scroll-area"], [data-control-family="sidebar"]) {
    scrollbar-color: auto;
    scrollbar-width: auto;
  }
  [data-skin="windows-98"] :where([data-control-family="scroll-area"][data-slot="root"]) {
    --cui-scroll-area-thumb-radius: 0;
    --cui-scroll-area-thumb-background: var(--win98-face);
    --cui-scroll-area-corner-background: var(--secondary);
  }
  [data-skin="windows-98"] :where([data-control-family="scroll-area"][data-slot="scrollbar"]) {
    background: var(--secondary);
  }
  [data-skin="windows-98"] :where([data-control-family="scroll-area"][data-slot="scrollbar"][data-orientation="vertical"]) {
    inline-size: 16px;
  }
  [data-skin="windows-98"] :where([data-control-family="scroll-area"][data-slot="scrollbar"][data-orientation="horizontal"]) {
    block-size: 16px;
  }
  [data-skin="windows-98"] :where([data-control-family="scroll-area"][data-slot="thumb"]) {
    border: 0;
    box-shadow: var(--win98-raised);
  }
  [data-skin="windows-98"] :where([data-control-family="scroll-area"], [data-control-family="sidebar"])::-webkit-scrollbar {
    width: 16px;
    height: 16px;
  }
  [data-skin="windows-98"] :where([data-control-family="scroll-area"], [data-control-family="sidebar"])::-webkit-scrollbar-track {
    background: repeating-conic-gradient(var(--win98-light) 0% 25%, var(--win98-white) 0% 50%) 0 0 / 2px 2px;
  }
  [data-skin="windows-98"] :where([data-control-family="scroll-area"], [data-control-family="sidebar"])::-webkit-scrollbar-thumb {
    background: var(--win98-face);
    box-shadow: var(--win98-raised);
  }
  @media (pointer: coarse) {
    [data-skin="windows-98"]
      :where(
        [data-control-family="button"][data-control="true"],
        [data-control-family="field"][data-control="true"],
        [data-control-family="sidebar"][data-slot="menu-button"],
        [data-control-family="popup"][data-popup-part="item"]
      ) {
      min-block-size: 44px;
    }
    [data-skin="windows-98"] :where([data-control-family="button"][data-popup-part="close"][data-icon-only="true"]) {
      top: 3px;
      right: 3px;
      width: 44px;
    }
  }
}

@layer components {
  @media (pointer: coarse) {
    [data-skin="windows-98"]
      :where([data-control-family="popup"][data-slot="title"]:is([data-popup-kind="dialog"], [data-popup-kind="alert-dialog"])) {
      min-block-size: 50px;
      padding-block: 17px;
      padding-inline-end: 52px;
    }
  }
  [data-skin="windows-98"]
    :where([data-control-family="toolbar"][data-slot="root"][data-variant="inverse"] [data-control-family="button"][data-control="true"]) {
    --cui-button-background: var(--cui-toolbar-item-background);
    --cui-button-background-image: none;
    --cui-button-foreground: var(--cui-toolbar-item-foreground);
    --cui-button-hover-background: var(--cui-toolbar-item-hover-background);
    --cui-button-hover-foreground: var(--cui-toolbar-item-hover-foreground);
    --cui-button-active-background: var(--cui-toolbar-item-active-background);
    --cui-button-active-foreground: var(--cui-toolbar-item-active-foreground);
    --cui-button-active-hover-background: var(--cui-toolbar-item-active-background);
    --cui-button-shadow: var(--cui-toolbar-item-shadow);
  }
}

[data-skin="windows-98"][data-skin] {
  --font-sans: Tahoma, Arial, sans-serif;
  --font-mono: "Lucida Console", Consolas, monospace;
  --text-body: 0.75rem;
  --text-caption: 0.6875rem;
  --text-body-lg: 0.8125rem;
  --background: oklch(1 0 0);
  --foreground: oklch(0.252 0 0);
  --card: oklch(0.8078 0 0);
  --card-foreground: oklch(0.252 0 0);
  --popover: oklch(0.8078 0 0);
  --popover-foreground: oklch(0.252 0 0);
  --primary: oklch(0.2711 0.1879 264.052);
  --primary-foreground: oklch(1 0 0);
  --muted: oklch(0.9037 0 0);
  --muted-foreground: oklch(0.4239 0 0);
  --secondary: oklch(0.8078 0 0);
  --secondary-foreground: oklch(0.252 0 0);
  --accent: oklch(0.2711 0.1879 264.052);
  --accent-foreground: oklch(1 0 0);
  --destructive: oklch(0.3767 0.1546 29.234);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.5999 0 0);
  --input: oklch(0.5999 0 0);
  --ring: oklch(0 0 0);
  --focus-ring: var(--foreground);
  --focus-ring-style: dotted;
  --focus-ring-width: 1px;
  --focus-ring-offset: -4px;
  --canvas: oklch(0.8078 0 0);
  --popover-opacity: 1;
  --backdrop-blur-popover: 0px;
  --overlay-opacity: 0.3;
  --backdrop-blur-overlay: 0px;
  --scroll-fade-size: 0rem;
  --shadow-color: oklch(0 0 0);
  --shadow-size: 0.4;
  --shadow-opacity: 1;
  --radius: 0rem;
  --radius-control: calc(var(--radius) * 2);
  --popover-padding: 2px;
  --radius-popup-item: calc(var(--radius-control) * 0.6);
  --padding-x: 0.625rem;
  --padding-y: 0.375rem;
  --control-h: 1.625rem;
  --ease-standard: linear;
  --ease-emphasized: linear;
  --duration-fast: 0ms;
  --duration-base: 0ms;
  --duration-slow: 0ms;
  --text-label: 0.6875rem;
  --radius-field: calc(var(--radius) * 2.2);
  --radius-panel: calc(var(--radius) * 2.6);
  --radius-scene: calc(var(--radius) * 2.8);
  --primary-text: var(--primary);
  --destructive-text: var(--destructive);
  --badge-red-foreground: oklch(from var(--color-red-800) 0.34 c h);
  --badge-orange-foreground: oklch(from var(--color-orange-800) 0.34 c h);
  --badge-yellow-foreground: oklch(from var(--color-yellow-800) 0.34 c h);
  --badge-green-foreground: oklch(from var(--color-green-800) 0.34 c h);
  --badge-blue-foreground: oklch(from var(--color-blue-800) 0.34 c h);
  --badge-purple-foreground: oklch(from var(--color-purple-800) 0.34 c h);
  --badge-pink-foreground: oklch(from var(--color-pink-800) 0.34 c h);
}

@layer components {
  [data-skin="windows-98"]
    :where(
      [data-control-family="button"],
      [data-control-family="field"],
      [data-control-family="choice"],
      [data-control-family="tabs"],
      [data-control-family="sidebar"],
      [data-control-family="tree"],
      [data-control-family="popup"],
      [data-control-family="kbd"]
    ) {
    font-family: "Control UI MS Sans Serif", Tahoma, Arial, sans-serif;
  }
  [data-skin="windows-98"] :where([data-control-family="button"][data-control="true"]) {
    --cui-button-radius: 0px;
    --cui-button-icon: 13px;
    --cui-button-gap: 4px;
    --cui-button-press-scale: 1;
    --cui-button-foreground: var(--foreground);
    --cui-button-hover-foreground: var(--foreground);
    --cui-button-hover-background: var(--win98-face);
    --cui-button-press-background: var(--win98-face);
    --cui-button-active-background: var(--win98-light);
    --cui-button-active-foreground: var(--foreground);
    --cui-button-active-hover-background: var(--win98-light);
    --cui-button-shadow: none;
    --cui-button-hover-shadow: inset 1px 1px var(--win98-white), inset -1px -1px var(--win98-shadow);
    --cui-button-press-shadow: var(--win98-pressed);
    --cui-button-active-shadow: var(--win98-pressed);
    line-height: 1;
    font-weight: 400;
  }
  [data-skin="windows-98"]
    :where([data-control-family="button"][data-control="true"]:is([data-variant="surface"], [data-variant="solid"])) {
    --cui-button-background: var(--win98-face);
    --cui-button-shadow: var(--win98-raised);
    --cui-button-hover-shadow: var(--win98-raised);
  }
  [data-skin="windows-98"] :where([data-control-family="button"][data-control="true"][data-variant="solid"]) {
    --cui-button-shadow: var(--win98-raised), 0 0 0 1px var(--win98-dark);
  }
  [data-skin="windows-98"]
    :where(
      [data-control-family="button"][data-control="true"]:is([data-variant="surface"], [data-variant="solid"]):not([data-icon-only="true"])
    ) {
    min-inline-size: 75px;
  }
  [data-skin="windows-98"] :where([data-control-family="button"][data-control="true"][data-tone="danger"]) {
    --cui-button-foreground: var(--destructive-text);
    --cui-button-hover-foreground: var(--destructive-text);
    --cui-button-active-foreground: var(--destructive-text);
  }
  [data-skin="windows-98"] :where([data-control-family="button"][data-control="true"]:disabled) {
    opacity: 1;
    --cui-button-foreground: var(--win98-shadow);
    text-shadow: 1px 1px var(--win98-white);
  }
  [data-skin="windows-98"] :where([data-control-family="field"][data-control="true"]) {
    --cui-field-radius: 0px;
    --cui-field-background: var(--background);
    --cui-field-foreground: var(--foreground);
    --cui-field-border-width: 0px;
    --cui-field-shadow: var(--win98-sunken);
    --cui-field-padding-inline: 4px;
    --cui-field-focus-border-color: var(--win98-dark);
  }
  [data-skin="windows-98"] :where([data-control-family="button"][data-control-ui="select"][data-slot="trigger"]) {
    --cui-button-background: var(--background);
    --cui-button-hover-background: var(--background);
    --cui-button-press-background: var(--background);
    --cui-button-shadow: var(--win98-sunken);
    --cui-button-hover-shadow: var(--win98-sunken);
    --cui-button-press-shadow: var(--win98-sunken);
    --cui-button-padding-inline: 4px;
  }
  [data-skin="windows-98"] :where([data-control-family="popup"][data-control-ui="select"][data-slot="icon"]) {
    align-self: stretch;
    width: 16px;
    margin: 2px -2px 2px 4px;
    background: var(--win98-face);
    box-shadow: var(--win98-raised);
    color: var(--foreground);
    rotate: 0deg;
  }
  [data-skin="windows-98"]
    :where(
      [data-control-family="choice"][data-slot="root"][data-choice-kind="checkbox"],
      [data-control-family="choice"][data-slot="item"][data-choice-kind="radio-group"]
    ) {
    --cui-choice-checked-background: var(--background);
    --cui-choice-border-color: transparent;
    --cui-choice-checked-border-color: transparent;
    inline-size: 13px;
    block-size: 13px;
    color: var(--foreground);
    background-color: var(--background);
    --cui-choice-shadow: var(--win98-sunken);
  }
  [data-skin="windows-98"] :where([data-control-family="choice"][data-slot="root"][data-choice-kind="checkbox"]) {
    --cui-choice-radius: 0px;
  }
  [data-skin="windows-98"] :where([data-control-family="choice"][data-slot="indicator"][data-choice-kind="radio-group"]) {
    inline-size: 5px;
    block-size: 5px;
    background: currentColor;
  }
  [data-skin="windows-98"] :where([data-control-family="switch"][data-slot="root"]) {
    --cui-switch-background: var(--win98-light);
    --cui-switch-hover-background: var(--win98-light);
    --cui-switch-thumb-radius: 0px;
    --cui-switch-thumb-background: var(--win98-face);
    --cui-switch-thumb-shadow: var(--win98-raised);
    border-radius: 0;
    box-shadow: var(--win98-sunken);
  }
  [data-skin="windows-98"] :where([data-control-family="tabs"][data-slot="root"]) {
    --cui-tabs-trigger-radius: 3px;
    --cui-tabs-list-padding: 0px;
    --cui-tabs-list-background: transparent;
    --cui-tabs-foreground: var(--foreground);
    --cui-tabs-active-foreground: var(--foreground);
    --cui-tabs-indicator-background: transparent;
    --cui-tabs-indicator-shadow: none;
  }
  [data-skin="windows-98"] :where([data-control-family="tabs"][data-slot="list"]) {
    gap: 0;
    align-items: end;
    border-bottom: 1px solid var(--win98-white);
  }
  [data-skin="windows-98"] :where([data-control-family="tabs"][data-slot="tab"]) {
    border-end-start-radius: 0;
    border-end-end-radius: 0;
    background: var(--win98-face);
    box-shadow:
      inset 1px 1px var(--win98-white),
      inset 2px 2px var(--win98-light),
      inset -1px 0 var(--win98-dark),
      inset -2px 0 var(--win98-shadow);
    font-weight: 400;
  }
  [data-skin="windows-98"] :where([data-control-family="tabs"][data-slot="tab"][aria-selected="true"]) {
    margin-bottom: -1px;
    padding-bottom: 2px;
    border-bottom: 1px solid var(--win98-face);
  }
  [data-skin="windows-98"] :where([data-control-family="range"][data-slot="root"]) {
    --cui-range-track-radius: 0px;
    --cui-range-track-background: var(--win98-face);
    --cui-range-indicator-radius: 0px;
    --cui-range-indicator-background: var(--primary);
    --cui-range-thumb-radius: 0px;
    --cui-range-thumb-background: var(--win98-face);
    --cui-range-thumb-border-color: transparent;
    --cui-range-thumb-shadow: var(--win98-raised);
  }
  [data-skin="windows-98"]
    :where([data-control-family="range"][data-slot="track"]:is([data-range-kind="progress"], [data-range-kind="meter"])) {
    block-size: 17px;
    padding: 2px;
    box-shadow: var(--win98-sunken);
  }
  [data-skin="windows-98"]
    :where([data-control-family="range"][data-slot="indicator"]:is([data-range-kind="progress"], [data-range-kind="meter"])) {
    max-block-size: 100%;
    mask-image: repeating-linear-gradient(90deg, oklch(0 0 0) 0 6px, transparent 6px 8px);
  }
  [data-skin="windows-98"] :where([data-control-family="range"][data-range-kind="slider"][data-slot="track"]:not([data-labeled])) {
    block-size: 4px;
    box-shadow: var(--win98-sunken);
  }
  [data-skin="windows-98"] :where([data-control-family="range"][data-range-kind="slider"][data-slot="thumb"][data-variant="default"]) {
    inline-size: 11px;
    block-size: 21px;
    scale: 1;
  }

  [data-skin="windows-98"] :where([data-control-family="field"][data-field-kind="native-select"][data-slot="icon"]) {
    display: grid;
    place-items: center;
    inset-block: 2px;
    right: 2px;
    inline-size: 17px;
    background: var(--win98-face);
    border: 0;
    border-radius: 0;
    box-shadow: var(--win98-raised);
  }
  [data-skin="windows-98"] :where([data-control-family="field"][data-field-kind="native-select"][data-slot="root"]) {
    padding-inline-end: 23px;
  }
  [data-skin="windows-98"]
    :where(
      [data-control-family="field"][data-field-kind="number-field"]:is(
        [data-control-family="field"][data-slot="increment"],
        [data-control-family="field"][data-slot="decrement"]
      )
    ) {
    background: var(--win98-face);
    box-shadow: var(--win98-raised);
    border: 0;
    border-radius: 0;
  }
  [data-skin="windows-98"]
    :where(
      [data-control-family="field"][data-field-kind="number-field"]:is(
        [data-control-family="field"][data-slot="increment"],
        [data-control-family="field"][data-slot="decrement"]
      ):active
    ) {
    box-shadow: var(--win98-pressed);
  }
}
